```java
public class SpeechRecognitionService {
    private final SpeechClient speechClient;
    private final BlockingQueue<byte[]> audioQueue;

    public SpeechRecognitionService(SpeechClient speechClient) {
        this.speechClient = speechClient;
        this.audioQueue = new LinkedBlockingQueue<>();
    }

    public void queueAudio(byte[] audioData) {
        audioQueue.offer(audioData);
    }

    public String recognizeSpeech(byte[] audioData) {
        // Configure recognition for Korean language
        RecognitionConfig config = RecognitionConfig.newBuilder()
            .setEncoding(RecognitionConfig.AudioEncoding.LINEAR16)
            .setSampleRateHertz(16000)
            .setLanguageCode("ko-KR")
            .setModel("latest_long")
            .setEnableAutomaticPunctuation(true)
            .setUseEnhanced(true)  // Use enhanced model
            .addSpeechContexts(SpeechContext.newBuilder()
                .addPhrases("게임", "마인크래프트", "명령어")  // Add game-specific Korean terms
                .build())
            .build();

        RecognitionAudio audio = RecognitionAudio.newBuilder()
            .setContent(ByteString.copyFrom(audioData))
            .build();

        RecognizeResponse response = speechClient.recognize(config, audio);
        StringBuilder transcript = new StringBuilder();
        for (SpeechRecognitionResult result : response.getResultsList()) {
            transcript.append(result.getAlternativesList().get(0).getTranscript());
        }
        return transcript.toString();
    }

    public void startProcessingQueue() {
        new Thread(() -> {
            while (true) {
                try {
                    byte[] audioData = audioQueue.take();
                    String text = recognizeSpeech(audioData);
                    // Handle recognized text
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }).start();
    }
}
```
