public class TextToSpeechService {
    private final TextToSpeechClient ttsClient;
    private final Map<String, VoiceSelectionParams> emotionVoices;
    private final VoiceSelectionParams defaultVoice;

    public TextToSpeechService() {
        this.ttsClient = TTSConfig.getClient();
        this.emotionVoices = initializeEmotionVoices();
        this.defaultVoice = VoiceSelectionParams.newBuilder()
            .setLanguageCode("ko-KR")
            .setName("ko-KR-Neural2-C")
            .setSsmlGender(SsmlVoiceGender.NEUTRAL)
            .build();
    }

    private Map<String, VoiceSelectionParams> initializeEmotionVoices() {
        Map<String, VoiceSelectionParams> voices = new HashMap<>();

        // Happy voice
        voices.put("happy", VoiceSelectionParams.newBuilder()
            .setLanguageCode("ko-KR")
            .setName("ko-KR-Neural2-B")
            .setSsmlGender(SsmlVoiceGender.FEMALE)
            .build());

        // Sad voice
        voices.put("sad", VoiceSelectionParams.newBuilder()
            .setLanguageCode("ko-KR")
            .setName("ko-KR-Neural2-D")
            .setSsmlGender(SsmlVoiceGender.MALE)
            .build());

        // Add more emotion mappings as needed

        return voices;
    }

    private double getEmotionPitch(String emotion) {
        switch (emotion.toLowerCase()) {
            case "happy": return 4.0;
            case "sad": return -2.0;
            case "angry": return 3.0;
            case "fearful": return 1.5;
            default: return 0.0;
        }
    }

    private double getEmotionRate(String emotion) {
        switch (emotion.toLowerCase()) {
            case "happy": return 1.2;
            case "sad": return 0.8;
            case "angry": return 1.3;
            case "fearful": return 1.1;
            default: return 1.0;
        }
    }

    public byte[] synthesizeSpeech(String text, String emotion) {
        VoiceSelectionParams voice = emotionVoices.getOrDefault(emotion, defaultVoice);

        SynthesisInput input = SynthesisInput.newBuilder()
            .setText(text)
            .build();

        AudioConfig audioConfig = AudioConfig.newBuilder()
            .setAudioEncoding(AudioEncoding.MP3)
            .setSpeakingRate(getEmotionRate(emotion))
            .setPitch(getEmotionPitch(emotion))
            .build();

        SynthesizeSpeechResponse response = ttsClient.synthesizeSpeech(input, voice, audioConfig);
        return response.getAudioContent().toByteArray();
    }
}
```
