private String addEmotionSSML(String text, String emotion) {
    StringBuilder ssml = new StringBuilder();
    ssml.append("<speak>");

    switch (emotion.toLowerCase()) {
        case "happy":
            ssml.append("<prosody rate=\"1.2\" pitch=\"+4st\">");
            ssml.append(addKoreanPauses(text));
            ssml.append("</prosody>");
            break;
        case "sad":
            ssml.append("<prosody rate=\"0.8\" pitch=\"-2st\">");
            ssml.append("<emphasis level=\"reduced\">");
            ssml.append(addKoreanPauses(text));
            ssml.append("</emphasis></prosody>");
            break;
        // Add more emotion cases
        default:
            ssml.append(addKoreanPauses(text));
    }

    ssml.append("</speak>");
    return ssml.toString();
}

private String addKoreanPauses(String text) {
    // Add natural pauses after sentence endings in Korean
    text = text.replaceAll("([.!?])", "$1<break time=\"500ms\"/>");
    // Add shorter pauses after commas
    text = text.replaceAll("(,)", "$1<break time=\"300ms\"/>");
    // Add pauses after specific Korean particles if needed
    return text;
}
