   public void changeBotSkin(String botName, String skinType) {
       Player botPlayer = Bukkit.getPlayer(botName);
       if (botPlayer == null || !botPlayer.isOnline()) return;

       PlayerProfile profile = skinProfiles.get(skinType);
       if (profile == null) return;

       // Apply skin change via protocol packets
       PacketContainer packet = new PacketContainer(PacketType.Play.Server.PLAYER_INFO);
       // Set packet data for skin change

       try {
           // Send packet to all players who can see the bot
           for (Player player : Bukkit.getOnlinePlayers()) {
               if (player.canSee(botPlayer)) {
                   ProtocolLibrary.getProtocolManager().sendServerPacket(player, packet);
               }
           }

           // Make the bot invisible briefly and then visible again to refresh the skin
           hideAndShowPlayer(botPlayer);
       } catch (Exception e) {
           plugin.getLogger().log(Level.SEVERE, "Error changing skin for " + botName, e);
       }
   }

   private void hideAndShowPlayer(Player player) {
       // Hide player from all players who can see them
       for (Player observer : Bukkit.getOnlinePlayers()) {
           if (observer.canSee(player)) {
               observer.hidePlayer(plugin, player);
               Bukkit.getScheduler().runTaskLater(plugin, () -> 
                   observer.showPlayer(plugin, player), 10L);
           }
       }
   }
