   public class EmotionDetector {
       private final Map<String, List<String>> emotionKeywords = new HashMap<>();

       public EmotionDetector() {
           initializeKeywords();
       }

       private void initializeKeywords() {
           // Map keywords to emotions
           emotionKeywords.put("happy", Arrays.asList("happy", "joy", "glad", "excited", "wonderful"));
           emotionKeywords.put("sad", Arrays.asList("sad", "unhappy", "depressed", "sorry", "regret"));
           // Add more emotions and keywords
       }

       public String detectEmotion(String message) {
           message = message.toLowerCase();

           // Find emotion with most keyword matches
           String dominantEmotion = "neutral";
           int maxMatches = 0;

           for (Map.Entry<String, List<String>> entry : emotionKeywords.entrySet()) {
               int matches = countMatches(message, entry.getValue());
               if (matches > maxMatches) {
                   maxMatches = matches;
                   dominantEmotion = entry.getKey();
               }
           }

           return dominantEmotion;
       }

       private int countMatches(String message, List<String> keywords) {
           int count = 0;
           for (String keyword : keywords) {
               if (message.contains(keyword)) count++;
           }
           return count;
       }
   }
   ```

