    private void ensureDefaults() {
        for (Map.Entry<String, Object> entry : defaultSettings.entrySet()) {
            if (!config.contains(entry.getKey())) {
                config.set(entry.getKey(), entry.getValue());
            }
        }
    }

    public void loadConfiguration() {
        plugin.reloadConfig();
        validateConfiguration();
    }

    public void saveConfiguration() {
        plugin.saveConfig();
    }

    private void validateConfiguration() {
        // Validate critical settings
        // Correct invalid settings
    }

    public <T> T getSetting(String path, Class<T> type) {
        if (!config.contains(path) && defaultSettings.containsKey(path)) {
            return (T) defaultSettings.get(path);
        }

        Object value = config.get(path);
        if (value != null && type.isInstance(value)) {
            return (T) value;
        }

        // Handle type conversion or return default
        return (T) defaultSettings.getOrDefault(path, null);
    }
}

