        try {
            File logsDir = new File(plugin.getDataFolder(), "logs");
            if (!logsDir.exists()) {
                logsDir.mkdirs();
            }

            logFile = new File(logsDir, "latest.log");
            fileHandler = new FileHandler(logFile.getPath(), true);
            fileHandler.setFormatter(new SimpleFormatter());
            logger.addHandler(fileHandler);

            // Set up log rotation
            setupLogRotation();
        } catch (IOException e) {
            logger.severe("Failed to set up file logging: " + e.getMessage());
        }
    }

    private void setupLogRotation() {
        // Implement log rotation logic
        // Check file size and rotate if needed
    }

    public void log(LogLevel level, String message) {
        LogLevel configLevel = LogLevel.valueOf(configManager.getSetting("logging.level", String.class));

        if (level.ordinal() >= configLevel.ordinal()) {
            switch (level) {
                case DEBUG:
                    if (configManager.getSetting("general.debugMode", Boolean.class)) {
                        logger.info("[DEBUG] " + message);
                    }
                    break;
                case INFO:
                    logger.info(message);
                    break;
                case WARNING:
                    logger.warning(message);
                    break;
                case ERROR:
                    logger.severe(message);
                    // Potentially trigger error reporting
                    reportError(message, null);
                    break;
            }
        }
    }

    public void reportError(String message, Throwable error) {
        // Log the error
        logger.severe(message + (error != null ? ": " + error.getMessage() : ""));

        // Record stack trace if available
        if (error != null) {
            StringWriter sw = new StringWriter();
            error.printStackTrace(new PrintWriter(sw));
            logger.severe(sw.toString());
        }

