public class ErrorHandler {
    private final Plugin plugin;
    private final ConfigurationManager configManager;
    private final LoggingManager loggingManager;
    private final Map<String, ErrorState> componentStates;
    private final Map<String, Integer> failureCounters;

    public enum ErrorSeverity {
        LOW, MEDIUM, HIGH, CRITICAL
    }

    private static class ErrorState {
        private boolean operational;
        private long lastFailure;
        private long recoveryAttemptTime;
        private int consecutiveFailures;

        public ErrorState() {
            this.operational = true;
            this.lastFailure = 0;
            this.recoveryAttemptTime = 0;
            this.consecutiveFailures = 0;
        }
    }

    public ErrorHandler(Plugin plugin, ConfigurationManager configManager, LoggingManager loggingManager) {
        this.plugin = plugin;
        this.configManager = configManager;
        this.loggingManager = loggingManager;
        this.componentStates = new HashMap<>();
        this.failureCounters = new HashMap<>();

        // Initialize component states
        initializeComponentStates();

        // Schedule recovery attempts
        scheduleRecoveryAttempts();
    }

    private void initializeComponentStates() {
        // Initialize states for all critical components
        componentStates.put("database", new ErrorState());
        componentStates.put("externalApi", new ErrorState());
        componentStates.put("fileSystem", new ErrorState());
        // Add more components as needed
    }

    public void handleError(String component, String errorMessage, Throwable error, ErrorSeverity severity) {
        // Update component state
        ErrorState state = componentStates.getOrDefault(component, new ErrorState());
        state.operational = severity != ErrorSeverity.CRITICAL;
        state.lastFailure = System.currentTimeMillis();
        state.consecutiveFailures++;
        componentStates.put(component, state);

        // Update failure counters
        failureCounters.put(component, failureCounters.getOrDefault(component, 0) + 1);

        // Log the error
        loggingManager.log(LoggingManager.LogLevel.ERROR, "[" + component + "] " + errorMessage);
        loggingManager.reportError("[" + component + "] " + errorMessage, error);

        // Notify users if necessary
        if (severity == ErrorSeverity.HIGH || severity == ErrorSeverity.CRITICAL) {
            notifyAdmins(component, errorMessage, severity);
        }

        // Attempt immediate recovery for certain components
        if (shouldAttemptImmediateRecovery(component, severity)) {
            attemptRecovery(component);
        }
    }

    private boolean shouldAttemptImmediateRecovery(String component, ErrorSeverity severity) {
        // Logic to determine if immediate recovery should be attempted
        return severity != ErrorSeverity.CRITICAL && 
               componentStates.get(component).consecutiveFailures < 3;
    }

    private void attemptRecovery(String component) {
        ErrorState state = componentStates.get(component);
        state.recoveryAttemptTime = System.currentTimeMillis();

        loggingManager.log(LoggingManager.LogLevel.INFO, "Attempting recovery for component: " + component);

        // Component-specific recovery logic
        switch (component) {
            case "database":
                // Attempt to reconnect to database
                break;
            case "externalApi":
                // Reset API client or connection
                break;
            case "fileSystem":
                // Verify file permissions and accessibility
                break;
            default:
                // Generic recovery attempt
                break;
        }

        // Update state based on recovery result
        boolean recoverySuccessful = performRecoveryCheck(component);
        state.operational = recoverySuccessful;
        if (recoverySuccessful) {
            state.consecutiveFailures = 0;
            loggingManager.log(LoggingManager.LogLevel.INFO, "Recovery successful for component: " + component);
        } else {
            loggingManager.log(LoggingManager.LogLevel.WARNING, "Recovery failed for component: " + component);
        }
    }

    private boolean performRecoveryCheck(String component) {
        // Implement component-specific health checks
        // Return true if component is now operational
        return false; // Placeholder
    }

    private void notifyAdmins(String component, String errorMessage, ErrorSeverity severity) {
        // Send notifications to server administrators
        String prefix = severity == ErrorSeverity.CRITICAL ? "§c[CRITICAL] " : "§e[WARNING] ";
        String message = prefix + "Issue detected with " + component + ": " + errorMessage;

        // Send message to operators
        for (Player player : Bukkit.getOnlinePlayers()) {
            if (player.isOp()) {
                player.sendMessage(message);
            }
        }

        // Log to console
        Bukkit.getConsoleSender().sendMessage(message);
    }

    private void scheduleRecoveryAttempts() {
        long interval = configManager.getSetting("errorHandling.recoveryIntervalMinutes", Long.class) * 1200L; // Convert minutes to ticks
        Bukkit.getScheduler().runTaskTimerAsynchronously(plugin, () -> {
            for (Map.Entry<String, ErrorState> entry : componentStates.entrySet()) {
                String component = entry.getKey();
                ErrorState state = entry.getValue();

                if (!state.operational && 
                    System.currentTimeMillis() - state.recoveryAttemptTime > 60000) { // At least 1 minute since last attempt
                    attemptRecovery(component);
                }
            }
        }, interval, interval);
    }

    public boolean isComponentOperational(String component) {
        ErrorState state = componentStates.get(component);
        return state != null && state.operational;
    }

    public Map<String, Object> getDiagnosticInfo() {
        Map<String, Object> diagnostics = new HashMap<>();

        // Add component states
        for (Map.Entry<String, ErrorState> entry : componentStates.entrySet()) {
            ErrorState state = entry.getValue();
            Map<String, Object> stateInfo = new HashMap<>();
            stateInfo.put("operational", state.operational);
            stateInfo.put("lastFailure", new Date(state.lastFailure));
            stateInfo.put("consecutiveFailures", state.consecutiveFailures);

            diagnostics.put("component." + entry.getKey(), stateInfo);
        }

        // Add failure statistics
        diagnostics.put("failureCounters", failureCounters);

        return diagnostics;
    }
}

Develop a SystemMonitor class that collects performance metrics, monitors system health, and triggers alerts for issues. Also, create comprehensive documentation for the entire system. Example implementation:

public class SystemMonitor {
    private final Plugin plugin;
    private final ConfigurationManager configManager;
    private final LoggingManager loggingManager;
    private final PerformanceManager performanceManager;
    private final ErrorHandler errorHandler;
    private final Map<String, Gauge> gauges;
    private final Map<String, Counter> counters;
    private boolean alertSilenced = false;
    private long alertSilencedUntil = 0;

    private interface Metric {
        String getName();
        Map<String, Object> getMetricData();
    }

    private class Gauge implements Metric {
        private final String name;
        private double value;
        private final double warningThreshold;
        private final double criticalThreshold;
        private final boolean isHigherBad; // true if higher values are bad

        public Gauge(String name, double initialValue, double warningThreshold, double criticalThreshold, boolean isHigherBad) {
            this.name = name;
            this.value = initialValue;
            this.warningThreshold = warningThreshold;
            this.criticalThreshold = criticalThreshold;
            this.isHigherBad = isHigherBad;
        }

        public void setValue(double value) {
            this.value = value;
            checkThresholds();
        }

        private void checkThresholds() {
            if (isHigherBad) {
                if (value >= criticalThreshold) {
                    triggerAlert(name, "Critical threshold exceeded: " + value, true);
                } else if (value >= warningThreshold) {
                    triggerAlert(name, "Warning threshold exceeded: " + value, false);
                }
            } else {
                if (value <= criticalThreshold) {
                    triggerAlert(name, "Critical threshold breached: " + value, true);
                } else if (value <= warningThreshold) {
                    triggerAlert(name, "Warning threshold breached: " + value, false);
                }
            }
        }

        @Override
        public String getName() {
            return name;
        }

        @Override
        public Map<String, Object> getMetricData() {
            Map<String, Object> data = new HashMap<>();
            data.put("value", value);
            data.put("warningThreshold", warningThreshold);
            data.put("criticalThreshold", criticalThreshold);
            return data;
        }
    }

    private class Counter implements Metric {
        private final String name;
        private int count;
        private final int warningThreshold;
        private final int criticalThreshold;
        private final int timeWindowSeconds;
        private final Queue<Long> eventTimes;

        public Counter(String name, int warningThreshold, int criticalThreshold, int timeWindowSeconds) {
            this.name = name;
            this.count = 0;
            this.warningThreshold = warningThreshold;
            this.criticalThreshold = criticalThreshold;
            this.timeWindowSeconds = timeWindowSeconds;
            this.eventTimes = new LinkedList<>();
        }

        public void increment() {
            count++;
            eventTimes.add(System.currentTimeMillis());
            pruneOldEvents();
            checkThresholds();
        }

        private void pruneOldEvents() {
            long cutoff = System.currentTimeMillis() - (timeWindowSeconds * 1000L);
            while (!eventTimes.isEmpty() && eventTimes.peek() < cutoff) {
                eventTimes.poll();
            }
        }

        private void checkThresholds() {
            int recentCount = eventTimes.size();
            if (recentCount >= criticalThreshold) {
                triggerAlert(name, "Critical event frequency: " + recentCount + " in " + timeWindowSeconds + " seconds", true);
            } else if (recentCount >= warningThreshold) {
                triggerAlert(name, "Warning event frequency: " + recentCount + " in " + timeWindowSeconds + " seconds", false);
            }
        }

        @Override
        public String getName() {
            return name;
        }

        @Override
        public Map<String, Object> getMetricData() {
            Map<String, Object> data = new HashMap<>();
            data.put("totalCount", count);
            data.put("recentCount", eventTimes.size());
            data.put("timeWindowSeconds", timeWindowSeconds);
            return data;
        }
    }

    public SystemMonitor(Plugin plugin, ConfigurationManager configManager, LoggingManager loggingManager, 
                        PerformanceManager performanceManager, ErrorHandler errorHandler) {
        this.plugin = plugin;
        this.configManager = configManager;
        this.loggingManager = loggingManager;
        this.performanceManager = performanceManager;
        this.errorHandler = errorHandler;
        this.gauges = new HashMap<>();
        this.counters = new HashMap<>();

        // Initialize metrics
        initializeMetrics();

        // Schedule periodic monitoring
        scheduleMonitoring();

        // Schedule periodic self-tests
        scheduleSelfTests();
    }

    private void initializeMetrics() {
        // CPU usage gauge
        gauges.put("system.cpuUsage", new Gauge("CPU Usage", 0.0, 
                configManager.getSetting("monitoring.cpu.warningThreshold", Double.class),
                configManager.getSetting("monitoring.cpu.criticalThreshold", Double.class),
                true));

        // Memory usage gauge
        gauges.put("system.memoryUsage", new Gauge("Memory Usage", 0.0,
                configManager.getSetting("monitoring.memory.warningThreshold", Double.class),
                configManager.getSetting("monitoring.memory.criticalThreshold", Double.class),
                true));

        // Error counter
        counters.put("system.errors", new Counter("System Errors",
                configManager.getSetting("monitoring.errors.warningThreshold", Integer.class),
                configManager.getSetting("monitoring.errors.criticalThreshold", Integer.class),
                configManager.getSetting("monitoring.errors.timeWindowSeconds", Integer.class)));

        // Add more metrics as needed
    }

    private void scheduleMonitoring() {
        long intervalSeconds = configManager.getSetting("monitoring.intervalSeconds", Long.class);
        Bukkit.getScheduler().runTaskTimerAsynchronously(plugin, () -> {
            // Update metrics
            updateMetrics();

            // Collect and log all metrics
            Map<String, Object> allMetrics = new HashMap<>();
            for (Metric metric : getAllMetrics()) {
                allMetrics.putAll(metric.getMetricData());
            }

            // Add system diagnostics
            allMetrics.putAll(errorHandler.getDiagnosticInfo());

            // Log metrics
            loggingManager.collectTelemetry(allMetrics);
        }, 20L, intervalSeconds * 20L); // Convert seconds to ticks
    }

    private List<Metric> getAllMetrics() {
        List<Metric> allMetrics = new ArrayList<>();
        allMetrics.addAll(gauges.values());
        allMetrics.addAll(counters.values());
        return allMetrics;
    }

    private void updateMetrics() {
        // Update CPU usage
        double cpuUsage = measureCpuUsage();
        gauges.get("system.cpuUsage").setValue(cpuUsage);

        // Update memory usage
        double memoryUsage = measureMemoryUsage();
        gauges.get("system.memoryUsage").setValue(memoryUsage);

        // Update other metrics as needed
    }

    private double measureCpuUsage() {
        // Implement CPU usage measurement
        // This is a simplified example
        OperatingSystemMXBean osBean = ManagementFactory.getOperatingSystemMXBean();
        if (osBean instanceof com.sun.management.OperatingSystemMXBean) {
            return ((com.sun.management.OperatingSystemMXBean) osBean).getProcessCpuLoad() * 100.0;
        }
        return 0.0;
    }

    private double measureMemoryUsage() {
        // Calculate memory usage percentage
        Runtime runtime = Runtime.getRuntime();
        long maxMemory = runtime.maxMemory();
        long allocatedMemory = runtime.totalMemory();
        long freeMemory = runtime.freeMemory();
        long usedMemory = allocatedMemory - freeMemory;
        return ((double) usedMemory / maxMemory) * 100.0;
    }

    private void scheduleSelfTests() {
        long intervalHours = configManager.getSetting("monitoring.selfTest.intervalHours", Long.class);
        long intervalTicks = intervalHours * 3600 * 20L; // Convert hours to ticks

        Bukkit.getScheduler().runTaskTimerAsynchronously(plugin, this::runSelfTests, intervalTicks, intervalTicks);
    }

    private void runSelfTests() {
        loggingManager.log(LoggingManager.LogLevel.INFO, "Running system self-tests");

        // Test database connectivity
        testDatabaseConnectivity();

        // Test external API connectivity
        testExternalApiConnectivity();

        // Test file system access
        testFileSystemAccess();

        // Add more self-tests as needed

        loggingManager.log(LoggingManager.LogLevel.INFO, "System self-tests completed");
    }

    private void testDatabaseConnectivity() {
